26	func (s *APIV1Service) resolveMentionTargets(ctx context.Context, content string) (map[int32]*store.User, error) {
27		targets := make(map[int32]*store.User)
28		if content == "" {
29			return targets, nil
30		}
31	
32		data, err := s.MarkdownService.ExtractAll([]byte(content))
33		if err != nil {
34			return nil, errors.Wrap(err, "failed to extract mentions")
35		}
36		if len(data.Mentions) == 0 {
37			return targets, nil
38		}
39	
40		normal := store.Normal
41		users, err := s.Store.ListUsers(ctx, &store.FindUser{
42			UsernameList: data.Mentions,
43			RowStatus:    &normal,
44		})
45		if err != nil {
46			return nil, errors.Wrap(err, "failed to resolve mention users")
47		}
48	
49		for _, user := range users {
50			targets[user.ID] = user
51		}
52	
53		return targets, nil
54	}
55	
56	func canUserAccessMentionContext(target *store.User, memo *store.Memo, relatedMemo *store.Memo) bool {
57		if target == nil || memo == nil {
58			return false
59		}
60	
61		if relatedMemo != nil {
62			if relatedMemo.Visibility == store.Private && target.ID != relatedMemo.CreatorID {
63				return false
64			}
65		}
66	
67		if memo.Visibility == store.Private && target.ID != memo.CreatorID {
68			return false
69		}
70	
71		return true
72	}
73	
74	func shouldSkipMentionInbox(target *store.User, memo *store.Memo, relatedMemo *store.Memo) bool {
75		if target == nil || memo == nil {
76			return true
77		}
78	
79		if target.ID == memo.CreatorID {
80			return true
81		}
82	
83		// Comment creation already generates a memo-comment inbox item for the parent creator.
84		if relatedMemo != nil && target.ID == relatedMemo.CreatorID && memo.Visibility != store.Private && memo.CreatorID != relatedMemo.CreatorID {
85			return true
86		}
87	
88		return !canUserAccessMentionContext(target, memo, relatedMemo)
89	}
90	
91	func (s *APIV1Service) dispatchMemoMentionNotifications(ctx context.Context, memo *store.Memo, relatedMemo *store.Memo, previousContent string) error {
92		if memo == nil {
93			return nil
94		}
95	
96		currentTargets, err := s.resolveMentionTargets(ctx, memo.Content)
97		if err != nil {
98			return err
99		}
100		if len(currentTargets) == 0 {
101			return nil
102		}
103	
104		previousTargets, err := s.resolveMentionTargets(ctx, previousContent)
105		if err != nil {
106			return err
107		}
108	
109		for userID, target := range currentTargets {
110			if _, exists := previousTargets[userID]; exists {
111				continue
112			}
113			if shouldSkipMentionInbox(target, memo, relatedMemo) {
114				continue
115			}
116	
117			payload := &storepb.InboxMessage_MemoMentionPayload{
118				MemoId: memo.ID,
119			}
120			if relatedMemo != nil {
121				payload.RelatedMemoId = relatedMemo.ID
122			}
123	
124			if _, err := s.createInboxWithEmailNotification(ctx, &store.Inbox{
125				SenderID:   memo.CreatorID,
126				ReceiverID: target.ID,
127				Status:     store.UNREAD,
128				Message: &storepb.InboxMessage{
129					Type: storepb.InboxMessage_MEMO_MENTION,
130					Payload: &storepb.InboxMessage_MemoMention{
131						MemoMention: payload,
132					},
133				},
134			}); err != nil {
135				return errors.Wrap(err, "failed to create mention inbox")
136			}
137		}
138	
139		return nil
140	}
141	
142	func (s *APIV1Service) dispatchMemoMentionNotificationsBestEffort(ctx context.Context, memo *store.Memo, relatedMemo *store.Memo, previousContent string) {
143		if err := s.dispatchMemoMentionNotifications(ctx, memo, relatedMemo, previousContent); err != nil {
144			slog.Warn("Failed to dispatch memo mention notifications", slog.Any("err", err), slog.Int64("memo_id", int64(memo.ID)))
145		}
146	}
